///
/// Color-valued properties (COLOR, BACKGROUND_COLOR, …) are emitted with the
/// `COLOR` value type; all other constraint/style properties are `F32`.
pub fn value_type_for(prop: u16) -> u8 {
    match prop {
        property_id::COLOR
        | property_id::BACKGROUND_COLOR
