[package]
name = "pathland-waterui"
version = "0.1.0"
edition = "2021"
publish = false
description = "Pathland opcode backend for WaterUI: producer (view -> opcodes) and consumer (opcodes -> view)"
license = "Apache-2.0"

[dependencies]
pathland-core = { path = "../lib/rust/crates/pathland-core" }
pathland-core-transport = { path = "../lib/rust/crates/pathland-core-transport" }
waterui-core = { path = "../waterui/core" }
waterui-layout = { path = "../waterui/components/foundation/layout" }
waterui-text = { path = "../waterui/components/foundation/text" }

//! # pathland-waterui
//!
//! A Pathland backend for WaterUI: the producer walks a WaterUI view tree and
//! emits the declarative structure as Pathland's 16-byte opcodes; the consumer
//! decodes those opcodes back into a retained node description that can be
//! reconstructed as WaterUI views.
//!
//! This crate is the "bridge": WaterUI owns change detection and native
//! rendering (via its own backends), while Pathland supplies the wire protocol
//! and transport. Neither side is aware of the other's private machinery.

pub mod consumer;
pub mod producer;

pub use consumer::Consumer;
pub use producer::Emitter;

//! Producer: walk a WaterUI view tree and emit Pathland opcodes.
//!
//! The emitter is a hand-rolled recursive walker over [`AnyView`]. It handles
//! the raw native leaf types it knows about (container, text, spacer) and
//! unwraps the two metadata wrappers WaterUI uses to smuggle state past the
//! type-erasure boundary (`Metadata<Environment>` for the stack axis,
//! `Metadata<Retain>` for watcher-guard lifetimes). Any other view is a
//! composite and is expanded via [`View::body`].

use pathland_core::{component_type, Guest, RingError};
use waterui_core::components::{Metadata, Retain};
use waterui_core::{AnyView, Environment, Native, Signal, View};
use waterui_layout::container::FixedContainer;
use waterui_layout::spacer::Spacer;
use waterui_layout::stack::Axis;
use waterui_text::TextConfig;

/// Sentinel parent id for the root node (the ring treats `0` as "no parent").
const ROOT_PARENT: u32 = 0;

/// Emits WaterUI views as Pathland opcodes into a [`Guest`] ring.
pub struct Emitter<'a> {
    guest: Guest<'a>,
    next_id: u32,
}

impl<'a> Emitter<'a> {
    /// Create an emitter writing into the given guest ring.
    pub fn new(guest: Guest<'a>) -> Self {
        Self { guest, next_id: 1 }
    }

    /// Emit a view as one frame, returning the id of the root node.
    pub fn emit<V: View>(&mut self, view: V, env: &Environment) -> Result<u32, RingError> {
        self.guest.begin_frame();
        let root = self.emit_any(AnyView::new(view), env, ROOT_PARENT)?;
        self.guest.end_frame();
        Ok(root)
    }

    fn alloc_id(&mut self) -> u32 {
        let id = self.next_id;
        self.next_id += 1;
        id
    }

    fn insert(&mut self, parent: u32, child: u32) -> Result<(), RingError> {
        if parent != ROOT_PARENT {
            self.guest.insert_child(parent, child, pathland_core::APPEND)?;
        }
        Ok(())
    }

    fn emit_any(
        &mut self,
        view: AnyView,
        env: &Environment,
        parent: u32,
    ) -> Result<u32, RingError> {
        // `Metadata<Environment>` carries a scoped environment (WaterUI injects
        // the stack `Axis` this way); recurse into the content with that env.
        if view.is::<Metadata<Environment>>() {
            let m = *view.downcast::<Metadata<Environment>>().expect("downcast environment");
            return self.emit_any(m.content, &m.value, parent);
        }
        // `Metadata<Retain>` keeps watcher guards alive for the subtree's
        // lifetime; unwrap it (the retained value is dropped, which for a
        // static tree holds no guards).
        if view.is::<Metadata<Retain>>() {
            let m = *view.downcast::<Metadata<Retain>>().expect("downcast retain");
            return self.emit_any(m.content, env, parent);
        }
        if view.is::<Native<FixedContainer>>() {
            let c = *view
                .downcast::<Native<FixedContainer>>()
                .expect("downcast container");
            return self.emit_container(c, env, parent);
        }
        if view.is::<Native<TextConfig>>() {
            let c = *view.downcast::<Native<TextConfig>>().expect("downcast text");
            return self.emit_text(c, parent);
        }
        if view.is::<Native<Spacer>>() {
            let _s = *view.downcast::<Native<Spacer>>().expect("downcast spacer");
            return self.emit_spacer(parent);
        }

        // Composite view: expand its body and keep walking.
        let body = view.body(env);
        self.emit_any(AnyView::new(body), env, parent)
    }

    fn emit_container(
        &mut self,
        container: Native<FixedContainer>,
        env: &Environment,
        parent: u32,
    ) -> Result<u32, RingError> {
        let (_layout, contents) = container.into_inner().into_inner();
        let axis = env.get::<Axis>().copied().unwrap_or(Axis::Vertical);
        let ct = if axis.is_horizontal() {
            component_type::HSTACK
        } else {
            component_type::VSTACK
        };

        let id = self.alloc_id();
        self.guest.create_node(id, ct)?;
        self.insert(parent, id)?;

        for child in contents {
            self.emit_any(child, env, id)?;
        }
        Ok(id)
    }

    fn emit_text(&mut self, config: Native<TextConfig>, parent: u32) -> Result<u32, RingError> {
        let config = config.into_inner();
        let text = config.content.get().to_plain().to_string();

        let id = self.alloc_id();
        self.guest.create_node(id, component_type::TEXT)?;
        self.insert(parent, id)?;
        self.guest.set_text(id, &text)?;
        Ok(id)
    }

    fn emit_spacer(&mut self, parent: u32) -> Result<u32, RingError> {
        let id = self.alloc_id();
        self.guest.create_node(id, component_type::SPACER)?;
        self.insert(parent, id)?;
        Ok(id)
    }
}

//! Consumer: decode Pathland opcode frames into a retained node description.
//!
//! This mirrors `pathland-render-gtk`'s `RenderTree`, but keeps no platform
//! widget — it retains only the declarative structure (`id → component, text,
//! properties, children`) so the frame can be inspected or rebuilt as WaterUI
//! views. Per Pathland's statelessness principle, this is a cache of the
//! renderer's own output, never application state.

use std::collections::BTreeMap;

use pathland_core::{category, style, tree, Frame};

/// A decoded node in the retained description.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Node {
    /// Protocol component type id (see `pathland_core::component_type`).
    pub component: u16,
    /// Text content set via `STYLE::SET_TEXT`, if any.
    pub text: Option<String>,
    /// Constraint/style properties (`propertyId → value`).
    pub properties: BTreeMap<u16, u32>,
    /// Child node ids in insertion order.
    pub children: Vec<u32>,
}

impl Node {
    fn new(component: u16) -> Self {
        Self {
            component,
            text: None,
            properties: BTreeMap::new(),
            children: Vec::new(),
        }
    }
}

/// Applies opcode frames incrementally into a retained node map.
#[derive(Debug, Default)]
pub struct Consumer {
    nodes: BTreeMap<u32, Node>,
}

impl Consumer {
    /// Create an empty consumer.
    #[must_use]
    pub fn new() -> Self {
        Self::default()
    }

    /// Apply a frame's opcodes, mutating the retained description.
    pub fn apply(&mut self, frame: &Frame<'_>) {
        for op in frame.opcodes() {
            match op.category() {
                category::TREE => self.apply_tree(op.command(), op),
                category::STYLE => self.apply_style(op.command(), op, frame),
                _ => {}
            }
        }
    }

    fn apply_tree(&mut self, command: u8, op: pathland_core::Opcode) {
        match command {
            tree::CREATE_NODE => {
                let id = op.a();
                let component = op.b() as u16;
                self.nodes.insert(id, Node::new(component));
            }
            tree::DELETE_NODE => {
                self.nodes.remove(&op.a());
            }
            tree::INSERT_CHILD => {
                let (parent, child) = (op.a(), op.b());
                if let Some(node) = self.nodes.get_mut(&parent) {
                    node.children.push(child);
                }
            }
            tree::REMOVE_CHILD => {
                let (parent, child) = (op.a(), op.b());
                if let Some(node) = self.nodes.get_mut(&parent) {
                    node.children.retain(|&c| c != child);
                }
            }
            tree::MOVE_CHILD => {
                let (parent, child, index) = (op.a(), op.b(), op.c());
                if let Some(node) = self.nodes.get_mut(&parent) {
                    node.children.retain(|&c| c != child);
                    let index = (index as usize).min(node.children.len());
                    node.children.insert(index, child);
                }
            }
            _ => {}
        }
    }

    fn apply_style(&mut self, command: u8, op: pathland_core::Opcode, frame: &Frame<'_>) {
        match command {
            style::SET_TEXT => {
                if let Ok(text) = frame.arena_str(op.b()) {
                    if let Some(node) = self.nodes.get_mut(&op.a()) {
                        node.text = Some(text.to_string());
                    }
                }
            }
            style::SET_PROPERTY => {
                let property = (op.b() & 0xFFFF) as u16;
                if let Some(node) = self.nodes.get_mut(&op.a()) {
                    node.properties.insert(property, op.c());
                }
            }
            _ => {}
        }
    }

    /// The retained node at `id`, if present.
    #[must_use]
    pub fn node(&self, id: u32) -> Option<&Node> {
        self.nodes.get(&id)
    }

    /// Number of retained nodes.
    #[must_use]
    pub fn len(&self) -> usize {
        self.nodes.len()
    }

    /// Whether the retained description is empty.
    #[must_use]
    pub fn is_empty(&self) -> bool {
        self.nodes.is_empty()
    }
}

//! Round-trip: WaterUI view → opcodes → retained description.

use pathland_core::{component_type, init_memory, Guest, Host, MemoryLayout};
use pathland_waterui::{Consumer, Emitter};
use waterui_core::Environment;
use waterui_layout::stack::vstack;
use waterui_text::text::text;

#[test]
fn vstack_of_text_round_trips() {
    let env = Environment::new();
    let view = vstack((text("hello"), text("world")));

    let layout = MemoryLayout::default();
    let mut mem = vec![0u8; layout.total_bytes()];
    init_memory(&mut mem, &layout);

    let root = {
        let mut emitter = Emitter::new(Guest::new(&mut mem, &layout));
        emitter.emit(view, &env).expect("emit")
    };

    let mut host = Host::new(&mut mem, &layout);
    let frames = host.frames();
    assert_eq!(frames.len(), 1);

    let mut consumer = Consumer::new();
    consumer.apply(&frames[0]);

    assert_eq!(consumer.len(), 3);

    let root_node = consumer.node(root).expect("root node");
    assert_eq!(root_node.component, component_type::VSTACK);
    assert_eq!(root_node.children.len(), 2);

    let first = consumer.node(root_node.children[0]).expect("first child");
    assert_eq!(first.component, component_type::TEXT);
    assert_eq!(first.text.as_deref(), Some("hello"));

    let second = consumer.node(root_node.children[1]).expect("second child");
    assert_eq!(second.component, component_type::TEXT);
    assert_eq!(second.text.as_deref(), Some("world"));
}

#[test]
fn hstack_of_text_round_trips() {
    let env = Environment::new();
    let view = waterui_layout::stack::hstack((text("a"), text("b")));

    let layout = MemoryLayout::default();
    let mut mem = vec![0u8; layout.total_bytes()];
    init_memory(&mut mem, &layout);

    let root = {
        let mut emitter = Emitter::new(Guest::new(&mut mem, &layout));
        emitter.emit(view, &env).expect("emit")
    };

    let mut host = Host::new(&mut mem, &layout);
    let mut consumer = Consumer::new();
    for frame in host.frames() {
        consumer.apply(&frame);
    }

    let root_node = consumer.node(root).expect("root node");
    assert_eq!(root_node.component, component_type::HSTACK);
    assert_eq!(root_node.children.len(), 2);
}

